/**
 * Checks whether a given string is a palindrome or not.
 *
 * A palindrome is a word, phrase, number, or other sequence of characters that reads the same backward as forward.
 *
 * @param string $s The input string to be checked.
 *
 * @return bool True if the string is a palindrome, False otherwise.
 */
function is_palindrome($s) {
    // Remove any leading or trailing whitespace from the input string
    $s = trim($s);

    // Convert the string to lowercase to make the comparison case-insensitive
    $s = strtolower($s);

    // Compare the string with its reverse
    // If they are the same, the string is a palindrome
    return $s === strrev($s);
}

